from collections import deque


class Snake:
    _STEPS = {"U": (-1, 0), "D": (1, 0), "L": (0, -1), "R": (0, 1)}

    def __init__(self, width, height, food):
        self._width = width
        self._height = height
        self._food = list(food)
        self._eaten = 0
        self._body = deque([(0, 0)])
        self._over = False

    @property
    def score(self):
        return self._eaten

    @property
    def body(self):
        return list(self._body)

    @property
    def food(self):
        return self._food[self._eaten] if self._eaten < len(self._food) else None

    @property
    def over(self):
        return self._over

    def move(self, direction):
        if direction not in self._STEPS:
            raise ValueError("Bad direction")
        if self._over:
            return -1
        d_row, d_col = self._STEPS[direction]
        row, col = self._body[0][0] + d_row, self._body[0][1] + d_col
        head = (row, col)
        if not (0 <= row < self._height and 0 <= col < self._width):
            self._over = True
            return -1
        eating = head == self.food
        occupied = list(self._body) if eating else list(self._body)[:-1]
        if head in occupied:
            self._over = True
            return -1
        self._body.appendleft(head)
        if eating:
            self._eaten += 1
        else:
            self._body.pop()
        return self._eaten
